import { Link, useForm } from '@inertiajs/react';
import { Button } from '@/Components/ui/Button';
import { ArrowLeft, ClipboardList } from 'lucide-react';
import { Banner, Field, Panel, SummaryLine, currency, input } from '@/Components/ui/kit';
import LineItemsEditor, { linesFromServer, linesTotal } from '@/Components/ui/LineItemsEditor';

// Edit only: client POs are generated by the pipeline, so `clientPurchaseOrder` is always provided.
// `from` = 'pipeline' when opened from the pipeline card: Cancel/back and the save redirect go to the board.
// Draft: "Save draft" keeps working on it; "Save & confirm" copies the items and amount to the transaction.
// Confirmed: saving updates the transaction again (until a delivery locks it).
export default function ClientPurchaseOrderForm({ catalog = [], clientPurchaseOrder: po, from = null }) {
    const isConfirmed = po.status === 'confirmed';
    const fromPipeline = from === 'pipeline';

    const { data, setData, put, processing, errors, clearErrors, transform } = useForm({
        from: fromPipeline ? 'pipeline' : '',
        client_po_number: po.client_po_number ?? '',
        client_po_date: po.client_po_date ?? '',
        note: po.note ?? '',
        confirm: false,
        items: linesFromServer(po.items, 'unit_price'),
    });

    const field = (name, value) => {
        setData(name, value);
        if (String(value).trim() !== '') clearErrors(name, 'client_po');
    };

    const save = (confirm) => {
        transform((d) => ({ ...d, confirm }));
        put(route('client-purchase-orders.update', po.id), { preserveScroll: true });
    };

    const submit = (e) => {
        e.preventDefault();
        save(false);
    };

    const listUrl = fromPipeline ? route('pipelines.index') : route('client-purchase-orders.index');
    const backLabel = fromPipeline ? 'Pipeline' : 'Client purchase orders';
    const units = data.items.reduce((s, r) => s + (Number(r.quantity) || 0), 0);
    const total = linesTotal(data.items, 'unit_price');
    const txAmount = Number(po.transaction?.amount ?? 0);
    const differs = Math.abs(total - txAmount) > 0.004;
    const hasErrors = Object.keys(errors).length > 0;

    return (
        <form onSubmit={submit} noValidate className="mx-auto w-full max-w-[1680px] p-4 sm:p-6">
            <Link href={listUrl} className="mb-4 inline-flex items-center gap-1.5 text-sm font-medium text-slate-500 hover:text-slate-900">
                <ArrowLeft className="h-4 w-4" /> {backLabel}
            </Link>

            <div className="grid items-start gap-5 xl:grid-cols-[minmax(0,1fr)_340px]">
                <div className="min-w-0 space-y-5">
                    {errors.client_po && <Banner tone="error">{errors.client_po}</Banner>}

                    <Panel title="Client's order" description="Copy these from the purchase order your client sent." icon={ClipboardList}>
                        <div className="grid gap-4 md:grid-cols-3">
                            <Field label="Client PO number" required htmlFor="client_po_number" error={errors.client_po_number}>
                                <input
                                    id="client_po_number"
                                    type="text"
                                    placeholder="Required to confirm"
                                    value={data.client_po_number}
                                    onChange={(e) => field('client_po_number', e.target.value)}
                                    className={input(errors.client_po_number)}
                                />
                            </Field>
                            <Field label="Client PO date" htmlFor="client_po_date" error={errors.client_po_date}>
                                <input
                                    id="client_po_date"
                                    type="date"
                                    value={data.client_po_date ?? ''}
                                    onChange={(e) => field('client_po_date', e.target.value)}
                                    className={input(errors.client_po_date)}
                                />
                            </Field>
                            <Field label="Client" htmlFor="client_name">
                                <input
                                    id="client_name"
                                    type="text"
                                    readOnly
                                    value={[po.client?.client_name, po.contact_person?.contact_person].filter(Boolean).join(' · ')}
                                    className={input(false)}
                                />
                            </Field>
                        </div>
                    </Panel>

                    <LineItemsEditor
                        items={data.items}
                        onChange={(v) => setData('items', v)}
                        catalog={catalog}
                        errors={errors}
                        clearErrors={clearErrors}
                        priceField="unit_price"
                        priceLabel="Unit price"
                        title="Items ordered by the client"
                        description={
                            po.quotation
                                ? `Started from ${po.quotation.quotation_number}. Change quantities, prices or remove lines to match the client's PO.`
                                : "Started from the transaction's items. Change them to match the client's PO."
                        }
                    />

                    <Panel title="Note">
                        <Field label="Note" htmlFor="note" error={errors.note}>
                            <input
                                id="note"
                                type="text"
                                maxLength={500}
                                placeholder="Optional"
                                value={data.note}
                                onChange={(e) => field('note', e.target.value)}
                                className={input(errors.note)}
                            />
                        </Field>
                    </Panel>
                </div>

                <aside className="xl:sticky xl:top-20">
                    <Panel
                        title={po.cpo_number}
                        description={
                            isConfirmed
                                ? 'Confirmed. Saving updates the transaction again.'
                                : 'Draft. Confirm it to update the transaction.'
                        }
                    >
                        <dl className="space-y-3">
                            <SummaryLine label="Transaction">{po.transaction?.name ?? '—'}</SummaryLine>
                            <SummaryLine label="Client PO no.">{data.client_po_number || '—'}</SummaryLine>
                            <SummaryLine label="Lines">{data.items.length}</SummaryLine>
                            <SummaryLine label="Units">{units}</SummaryLine>
                        </dl>

                        <div className="mt-4 flex items-baseline justify-between border-t border-slate-100 pt-4">
                            <span className="text-sm text-slate-500">Total</span>
                            <span className="text-2xl font-semibold tabular-nums text-slate-900">{currency(total)}</span>
                        </div>

                        {!isConfirmed && differs && (
                            <Banner tone="warning" className="mt-4">
                                The transaction is currently {currency(txAmount)}. Confirming changes it to {currency(total)}.
                            </Banner>
                        )}
                        {hasErrors && !errors.client_po && (
                            <Banner tone="error" className="mt-4">Fix the highlighted fields before saving.</Banner>
                        )}

                        <div className="mt-5 flex flex-col gap-2">
                            {isConfirmed ? (
                                <Button type="submit" variant="brand" className="w-full" disabled={processing}>
                                    {processing ? 'Saving…' : 'Save changes'}
                                </Button>
                            ) : (
                                <>
                                    <Button type="button" variant="brand" className="w-full" disabled={processing} onClick={() => save(true)}>
                                        {processing ? 'Saving…' : 'Save & confirm'}
                                    </Button>
                                    <Button type="submit" variant="outline" className="w-full" disabled={processing}>
                                        Save draft
                                    </Button>
                                </>
                            )}
                            <Link href={listUrl} className="block">
                                <Button type="button" variant="outline" className="w-full">Cancel</Button>
                            </Link>
                        </div>
                    </Panel>
                </aside>
            </div>
        </form>
    );
}